cause.temporary_hook_source:
#include <cstddef>
#include <cstdio>
#include <sanitizer/common_interface_defs.h>

extern "C" void __sanitizer_malloc_hook(const volatile void* pointer, std::size_t size) {
    static thread_local bool reporting = false;
    if (reporting || (size != 104 && size != 144)) return;
    reporting = true;
    std::fprintf(stderr, "[DEBUG-issue70-allocation] size=%zu address=%p\n", size, const_cast<const void*>(pointer));
    __sanitizer_print_stack_trace();
    reporting = false;
}

cause.initial_instrumented_probe_source:
#include <vulkan/vulkan.h>
#include <cstdio>
#include <cstdlib>
#include <fstream>
#include <sanitizer/lsan_interface.h>

int main(int argc, char** argv) {
    const int cycles = argc > 1 ? std::atoi(argv[1]) : 1;
    const int enumerations = argc > 2 ? std::atoi(argv[2]) : 1;
    for (int cycle = 0; cycle < cycles; ++cycle) {
        VkInstanceCreateInfo info{};
        info.sType = VK_STRUCTURE_TYPE_INSTANCE_CREATE_INFO;
        VkInstance instance{};
        if (vkCreateInstance(&info, nullptr, &instance) != VK_SUCCESS) return 1;
        for (int enumeration = 0; enumeration < enumerations; ++enumeration) {
            unsigned count = 0;
            const VkResult result = vkEnumeratePhysicalDevices(instance, &count, nullptr);
            std::printf("cycle=%d enumeration=%d result=%d devices=%u\n", cycle, enumeration, result, count);
            if (result != VK_SUCCESS) return 2;
        }
        if (argc > 3) {
            std::ifstream maps("/proc/self/maps");
            std::ofstream output("build/issue70-evidence/probe-maps.txt");
            output << maps.rdbuf();
            __lsan_do_recoverable_leak_check();
        }
        vkDestroyInstance(instance, nullptr);
    }
}
